// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    function setUp() public { c = new DepositLog(); }
    function testFuzz_property(address logger, bool status) public {
        // Owner is the zero address (no constructor assignment), so prank it to
        // pass onlyOwner; domain stays fully wide over logger/status.
        vm.prank(address(0));
        c.setApprovedLogger(logger, status);
        assertTrue(c.approvedLoggers(logger) == status, "mapping must reflect requested status");
    }
}
